//   tile 32x64, hidden chunk 128, K step 32, 256 threads
__global__ void k_gemm_gemm_fused_0(__half* __restrict__ T_out_mlp_b2, const __half* __restrict__ T_out_attn_pv, const __half* __restrict__ P_W1, const float* __restrict__ P_b1, const __half* __restrict__ P_W2, const float* __restrict__ P_b2) {
