    for (int i = 0; i < 2; ++i) {
        #pragma unroll
        for (int j = 0; j < 4; ++j) accY[i][j] = 0.0f;
    }

    for (int hc = 0; hc < 1024; hc += 128) {
        // ---- phase 1: hidden tile = act(A x W1 + b1), written straight into shared memory ----
        if (threadIdx.x < 128) b1s[threadIdx.x] = P_b1[hc + threadIdx.x];
        float part[4][4];
        #pragma unroll
        for (int i = 0; i < 4; ++i) {
            #pragma unroll
            for (int j = 0; j < 4; ++j) part[i][j] = 0.0f;
        }
        #pragma unroll
        for (int k0 = 0; k0 < 256; k0 += 32) {
