                const int r = t / 32, c = t - (t / 32) * 32;
                As[r][c] = T_out_attn_pv[(rowBase + r) * 256 + (k0 + c)];
            }
            for (int t = threadIdx.x; t < 4096; t += 256) {
                const int r = t / 128, c = t - (t / 128) * 128;
                W1s[r][c] = P_W1[(k0 + r) * 1024 + (hc + c)];
            }
            __syncthreads();
            if (hiddenActive) {
