                for (int kk = 0; kk < 32; ++kk) {
                    float av[4], wv[4];
                    #pragma unroll
                    for (int i = 0; i < 4; ++i) av[i] = __half2float(As[r0 + i][kk]);
                    #pragma unroll
                    for (int j = 0; j < 4; ++j) wv[j] = __half2float(W1s[kk][h0 + j]);
                    #pragma unroll
                    for (int i = 0; i < 4; ++i) {
                        #pragma unroll
                        for (int j = 0; j < 4; ++j) part[i][j] = fmaf(av[i], wv[j], part[i][j]);
