// kernel 1: single
//   out.attn_scores = out.attn_scores  (512x512 = 512x256 x transpose (512x256))
//   tile 64x64, depth step 32, 256 threads, 4x4 per thread
__global__ void k_out_attn_scores(float* __restrict__ T_out_attn_scores, const __half* __restrict__ P_Q, const __half* __restrict__ P_K) {
