    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        #pragma unroll
        for (int j = 0; j < 4; ++j) acc[i][j] = 0.0f;
    }

    #pragma unroll
    for (int k0 = 0; k0 < 256; k0 += 32) {
        // cooperative tile load. Pascal has no cp.async, so global->shared is a plain
        // load/store pair guarded by __syncthreads() instead of an async copy.
        #pragma unroll
        for (int t = 0; t < 8; ++t) {   // A tile: 2048 elements
            const int idx = threadIdx.x + t * 256;
            const int ar = idx / 32;
            const int ac = idx - ar * 32;
            smA[ar][ac] = P_Q[(rowBase + ar) * 256 + (k0 + ac)];
        }
        #pragma unroll
        for (int t = 0; t < 8; ++t) {   // B tile: 2048 elements
            const int idx = threadIdx.x + t * 256;
            const int bmRow = idx - (idx / 32) * 32;   // k index inside the tile
            const int bmCol = idx / 32;                  // n index inside the tile
            smB[bmRow][bmCol] = P_K[(colBase + bmCol) * 256 + (k0 + bmRow)];
        }
        __syncthreads();

        #pragma unroll
        for (int kk = 0; kk < 32; ++kk) {
            float av[4], bv[4];
            #pragma unroll
            for (int i = 0; i < 4; ++i) av[i] = __half2float(smA[ty * 4 + i][kk]);
            #pragma unroll
            for (int j = 0; j < 4; ++j) bv[j] = __half2float(smB[kk][tx * 4 + j]);
            #pragma unroll
            for (int i = 0; i < 4; ++i) {
                #pragma unroll
                for (int j = 0; j < 4; ++j) acc[i][j] += av[i] * bv[j];
            }
        }
        __syncthreads();
