// kernel 2: softmax over 512 rows x 512 columns, 256 threads/block
__global__ void k_out_attn_softmax(__half* __restrict__ T_out_attn_softmax, const float* __restrict__ T_out_attn_scores) {
    __shared__ float scratch[8];
