    for (int j = threadIdx.x; j < 512; j += 256) s += expf(T_out_attn_scores[(long)row * 512 + j] - m);
    s = fx_block_sum(s, scratch);
    const float inv = 1.0f / s;
    for (int j = threadIdx.x; j < 512; j += 256) {
        T_out_attn_softmax[(long)row * 512 + j] = __float2half(expf(T_out_attn_scores[(long)row * 512 + j] - m) * inv);
    }
